  partC: { title: 'Fix the patrol', pts: 'Each patrol has a bug.', instr: 'Read the patrol and the problem. Write the fixed patrol.', colA: 'Patrol and problem', colB: 'Fixed patrol',
    rows: [
      { a: `${code('until no tanks [ F L X R ]')}<br><small>Tanks are only above some squares. The rover runs out of shells.</small>`, key: code('until no tanks [ F L if tank [ X ] R ]') },
      { a: `${code('until no tanks [ F L if tank [ X ] ]')}<br><small>The rover drives up into the rocks.</small>`, key: `${code('until no tanks [ F L if tank [ X ] R ]')} (turn back)` },
      { a: `${code('until no tanks [ F L if tank [ X ] R ]')}<br><small>The tanks are below the road.</small>`, key: code('until no tanks [ F R if tank [ X ] L ]') },
      { a: `${code('repeat 2 [ F L if tank [ X ] R ]')}<br><small>There are 6 squares with tanks somewhere above them.</small>`, key: `${code('until no tanks [ F L if tank [ X ] R ]')} (or repeat 6)` },
    ] },
  design: DESIGN.tank,
